#![forbid(unsafe_code)]

//! Deterministic household-demand simulation for the InstantClean hybrid
//! QuickCell + FullLoad architecture.
//!
//! All process-profile resource values are explicit inputs. The simulator does
//! not infer real appliance performance and does not model soil removal.
//! Cleaning/rinse eligibility is a hard gate: a process can be selected only
//! when its profile is marked validated and supports the job's soil and hygiene
//! requirements. Those profile flags are assumptions supplied by the caller,
//! not certifications generated by this crate.

pub mod resource_curve;

use std::collections::HashSet;

use symthaea_dishwasher_design::quality::{
    Endpoint, EndpointCriterion, PilotEvidenceEnvelope,
};

const ALL_SOILS_MASK: u8 = 0b0001_1111;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(u8)]
pub enum SoilClass {
    Protein = 0,
    Starch = 1,
    Fat = 2,
    Beverage = 3,
    Mixed = 4,
}

impl SoilClass {
    pub const fn mask(self) -> u8 {
        1_u8 << (self as u8)
    }

    pub const fn as_label(self) -> &'static str {
        match self {
            SoilClass::Protein => "protein",
            SoilClass::Starch => "starch",
            SoilClass::Fat => "fat",
            SoilClass::Beverage => "beverage",
            SoilClass::Mixed => "mixed",
        }
    }

    pub fn from_label(value: &str) -> Option<Self> {
        match value {
            "protein" => Some(SoilClass::Protein),
            "starch" => Some(SoilClass::Starch),
            "fat" => Some(SoilClass::Fat),
            "beverage" => Some(SoilClass::Beverage),
            "mixed" => Some(SoilClass::Mixed),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Job {
    pub id: u64,
    pub arrival_s: u64,
    pub deadline_s: u64,
    pub soil: SoilClass,
    pub requires_sanitization: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ModeProfile {
    pub name: String,
    pub capacity: usize,
    pub duration_s: u64,
    pub base_energy_kwh: f64,
    pub energy_per_item_kwh: f64,
    pub base_fresh_water_l: f64,
    pub fresh_water_per_item_l: f64,
    pub supported_soils_mask: u8,
    pub supports_sanitization: bool,
    /// Caller assertion that cleaning and final-rinse gates are validated.
    /// This is not established or audited by this simulator.
    pub cleaning_and_rinse_validated: bool,
}

impl ModeProfile {
    fn validate(&self, expected_capacity: Option<usize>) -> Result<(), &'static str> {
        if self.name.trim().is_empty() {
            return Err("mode name must not be empty");
        }
        if self.capacity == 0 || expected_capacity.is_some_and(|n| self.capacity != n) {
            return Err("mode capacity is invalid for this mode");
        }
        if self.duration_s == 0 {
            return Err("mode duration must be positive");
        }
        let resources = [
            self.base_energy_kwh,
            self.energy_per_item_kwh,
            self.base_fresh_water_l,
            self.fresh_water_per_item_l,
        ];
        if resources.iter().any(|x| !x.is_finite() || *x < 0.0) {
            return Err("mode resource coefficients must be finite and non-negative");
        }
        if self.supported_soils_mask & !ALL_SOILS_MASK != 0 {
            return Err("mode soil mask contains unknown soil classes");
        }
        Ok(())
    }

    pub fn supports(&self, job: &Job) -> bool {
        self.cleaning_and_rinse_validated
            && (self.supported_soils_mask & job.soil.mask()) != 0
            && (!job.requires_sanitization || self.supports_sanitization)
    }

    fn energy_for(&self, item_count: usize) -> f64 {
        self.base_energy_kwh + self.energy_per_item_kwh * item_count as f64
    }

    fn water_for(&self, item_count: usize) -> f64 {
        self.base_fresh_water_l + self.fresh_water_per_item_l * item_count as f64
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EvidenceBoundModeError {
    EmptyPilotEvidence,
    InvalidCapacity,
    SanitizationRequiresSeparateCertification,
    InvalidBaseProfile(&'static str),
    ProgrammeMismatch,
    UnsupportedSoilClass(String),
    MissingRequiredEndpoint(Endpoint),
    InsufficientPilotRuns,
    InconsistentPhysicalScope,
    InconsistentAcceptanceCriteria { soil: SoilClass },
    DuplicateSoilOccupancy {
        soil: SoilClass,
        occupancy: usize,
    },
    MissingSoilOccupancy {
        soil: SoilClass,
        occupancy: usize,
    },
}

/// A process profile whose supported soil/occupancy grid is derived from
/// independent pilot outcome evidence rather than the caller's boolean flag.
///
/// This does not certify the appliance, authenticate the evidence, provide
/// sanitization approval or validate resource coefficients. Resource curves
/// must be measured independently and the five-run pilot floor is not a
/// confirmatory sample-size calculation.
#[derive(Debug, Clone, PartialEq)]
pub struct EvidenceBoundMode {
    profile: ModeProfile,
    pilot_evidence: Vec<PilotEvidenceEnvelope>,
}

impl EvidenceBoundMode {
    /// Bind one exact mode/programme to a complete pilot-evidence ladder.
    ///
    /// For each supported soil class, evidence is required at every occupancy
    /// from 1 through the mode capacity. All envelopes must use the same machine,
    /// programme, surface, detergent/water batches and operating conditions.
    /// The adapter does not accept sanitization claims; those require separate
    /// certification evidence and a different API.
    pub fn from_pilot_evidence(
        mut profile: ModeProfile,
        pilot_evidence: Vec<PilotEvidenceEnvelope>,
    ) -> Result<Self, EvidenceBoundModeError> {
        if pilot_evidence.is_empty() {
            return Err(EvidenceBoundModeError::EmptyPilotEvidence);
        }
        if profile.capacity == 0 || profile.capacity > 64 {
            return Err(EvidenceBoundModeError::InvalidCapacity);
        }
        if profile.supports_sanitization {
            return Err(EvidenceBoundModeError::SanitizationRequiresSeparateCertification);
        }

        let first_scope = pilot_evidence[0].scope();
        if profile.name != first_scope.programme {
            return Err(EvidenceBoundModeError::ProgrammeMismatch);
        }
        let required = [
            Endpoint::SoilRemovalResidual,
            Endpoint::FinalRinseResidue,
            Endpoint::CrossContamination,
        ];
        let mut supported_soils = 0_u8;
        let mut soil_occupancies = HashSet::new();
        let mut acceptance_by_soil: HashMap<
            SoilClass,
            (Vec<EndpointCriterion>, Vec<(Endpoint, String)>),
        > = HashMap::new();

        for envelope in &pilot_evidence {
            let scope = envelope.scope();
            if scope.machine_model != first_scope.machine_model
                || scope.programme != first_scope.programme
                || scope.surface_material != first_scope.surface_material
                || scope.detergent_batch_id != first_scope.detergent_batch_id
                || scope.water_batch_id != first_scope.water_batch_id
                || scope.water_hardness_ppm_as_caco3
                    != first_scope.water_hardness_ppm_as_caco3
                || scope.inlet_temperature_millic != first_scope.inlet_temperature_millic
                || scope.ambient_temperature_millic != first_scope.ambient_temperature_millic
                || scope.ambient_relative_humidity_permille
                    != first_scope.ambient_relative_humidity_permille
                || scope.protocol_id != first_scope.protocol_id
            {
                return Err(EvidenceBoundModeError::InconsistentPhysicalScope);
            }
            let soil = SoilClass::from_label(&scope.soil_class)
                .ok_or_else(|| EvidenceBoundModeError::UnsupportedSoilClass(
                    scope.soil_class.clone(),
                ))?;
            let acceptance_identity = (
                envelope.criteria().to_vec(),
                envelope.method_ids().to_vec(),
            );
            match acceptance_by_soil.get(&soil) {
                Some(existing) if existing != &acceptance_identity => {
                    return Err(EvidenceBoundModeError::InconsistentAcceptanceCriteria {
                        soil,
                    });
                }
                None => {
                    acceptance_by_soil.insert(soil, acceptance_identity);
                }
                _ => {}
            }
            let occupancy = scope.item_ids.len();
            if occupancy == 0 || occupancy > profile.capacity {
                return Err(EvidenceBoundModeError::InvalidCapacity);
            }
            if envelope.minimum_independent_runs() < 5 {
                return Err(EvidenceBoundModeError::InsufficientPilotRuns);
            }
            for endpoint in required {
                if !envelope.required_endpoints().contains(&endpoint) {
                    return Err(EvidenceBoundModeError::MissingRequiredEndpoint(endpoint));
                }
            }
            if !soil_occupancies.insert((soil, occupancy)) {
                return Err(EvidenceBoundModeError::DuplicateSoilOccupancy {
                    soil,
                    occupancy,
                });
            }
            supported_soils |= soil.mask();
        }

        for soil in [
            SoilClass::Protein,
            SoilClass::Starch,
            SoilClass::Fat,
            SoilClass::Beverage,
            SoilClass::Mixed,
        ] {
            if supported_soils & soil.mask() != 0 {
                for occupancy in 1..=profile.capacity {
                    if !soil_occupancies.contains(&(soil, occupancy)) {
                        return Err(EvidenceBoundModeError::MissingSoilOccupancy {
                            soil,
                            occupancy,
                        });
                    }
                }
            }
        }

        profile.supported_soils_mask = supported_soils;
        profile.cleaning_and_rinse_validated = true;
        profile.supports_sanitization = false;
        profile
            .validate(None)
            .map_err(EvidenceBoundModeError::InvalidBaseProfile)?;

        Ok(Self {
            profile,
            pilot_evidence,
        })
    }

    pub fn profile(&self) -> &ModeProfile {
        &self.profile
    }

    pub fn pilot_evidence(&self) -> &[PilotEvidenceEnvelope] {
        &self.pilot_evidence
    }
}

/// Run the household scheduler using evidence-bound pilot mode profiles.
///
/// This is still a research simulator: the profile's energy/water coefficients
/// are caller inputs and must be replaced with measured occupancy curves before
/// resource-superiority claims. Sanitization-required jobs remain ineligible.
pub fn simulate_with_pilot_evidence(
    jobs: &[Job],
    quick: &EvidenceBoundMode,
    full: &EvidenceBoundMode,
    policy: Policy,
) -> Result<SimulationResult, &'static str> {
    simulate(jobs, quick.profile(), full.profile(), policy)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Policy {
    FullLoadOnly { max_batch_wait_s: u64 },
    QuickCellOnly,
    /// Offline benchmark policy that may use the replay trace's known future arrivals.
    /// This is an optimistic look-ahead reference, not a deployable controller.
    HybridResourceAware { max_batch_wait_s: u64 },
    /// Conservative hybrid policy. It estimates full-load completion using only
    /// currently pending work and the configured maximum batch wait.
    HybridConservativeNoOracle { max_batch_wait_s: u64 },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModeKind {
    QuickCell,
    FullLoad,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Completion {
    pub job_id: u64,
    pub mode: ModeKind,
    pub arrival_s: u64,
    pub started_s: u64,
    pub finished_s: u64,
    pub wait_s: u64,
    pub deadline_missed: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Operation {
    pub mode: ModeKind,
    pub started_s: u64,
    pub finished_s: u64,
    pub job_ids: Vec<u64>,
    pub energy_kwh: f64,
    pub fresh_water_l: f64,
}

#[derive(Debug, Clone, PartialEq)]
pub struct SimulationResult {
    pub completions: Vec<Completion>,
    pub operations: Vec<Operation>,
    pub unprocessed_job_ids: Vec<u64>,
    pub total_energy_kwh: f64,
    pub total_fresh_water_l: f64,
    pub quick_cell_cycles: usize,
    pub full_load_cycles: usize,
    pub deadline_misses: usize,
    /// Time from arrival until service starts.
    pub mean_wait_s: f64,
    pub p95_wait_s: u64,
    /// End-to-end time from arrival until the item is released clean/rinsed.
    pub mean_latency_s: f64,
    pub p95_latency_s: u64,
    /// Elapsed time from the first job arrival until the last completion.
    pub makespan_s: u64,
}

impl SimulationResult {
    pub fn completed_items(&self) -> usize {
        self.completions.len()
    }

    pub fn energy_per_completed_item_kwh(&self) -> Option<f64> {
        (!self.completions.is_empty())
            .then(|| self.total_energy_kwh / self.completions.len() as f64)
    }

    pub fn water_per_completed_item_l(&self) -> Option<f64> {
        (!self.completions.is_empty())
            .then(|| self.total_fresh_water_l / self.completions.len() as f64)
    }

    pub fn p95_wait_minutes(&self) -> f64 {
        self.p95_wait_s as f64 / 60.0
    }
}

fn predicted_full_finish(
    now_s: u64,
    pending: &[Job],
    future_jobs: &[Job],
    full: &ModeProfile,
    full_free_s: u64,
    max_wait_s: u64,
) -> Option<u64> {
    let eligible: Vec<&Job> = pending.iter().filter(|job| full.supports(job)).collect();
    if eligible.is_empty() {
        return None;
    }

    let current_count = eligible.len();
    let oldest_arrival = eligible.iter().map(|job| job.arrival_s).min()?;
    let timeout_at = oldest_arrival.saturating_add(max_wait_s);

    let ready_at = if current_count >= full.capacity {
        now_s
    } else {
        let needed = full.capacity - current_count;
        let capacity_at = future_jobs
            .iter()
            .filter(|job| full.supports(job))
            .nth(needed - 1)
            .map(|job| job.arrival_s);
        capacity_at.map_or(timeout_at, |arrival| arrival.min(timeout_at))
    };

    Some(now_s.max(full_free_s).max(ready_at).saturating_add(full.duration_s))
}

/// True when processing a partial FullLoad batch serially in QuickCell is
/// no worse on energy, fresh water and total queue service duration, and is
/// strictly better on at least one. This prevents a resource-only switch from
/// silently creating a much longer queue. Eligibility remains a hard gate.
fn quick_dominates_partial_batch(
    quick: &ModeProfile,
    full: &ModeProfile,
    batch_item_count: usize,
) -> bool {
    if batch_item_count == 0 {
        return false;
    }
    let quick_energy = quick.energy_for(1);
    let quick_water = quick.water_for(1);
    let full_energy_per_item = full.energy_for(batch_item_count) / batch_item_count as f64;
    let full_water_per_item = full.water_for(batch_item_count) / batch_item_count as f64;
    let quick_queue_duration_s = quick.duration_s.saturating_mul(batch_item_count as u64);
    let tolerance = 1.0e-12;

    let no_worse = quick_energy <= full_energy_per_item + tolerance
        && quick_water <= full_water_per_item + tolerance
        && quick_queue_duration_s <= full.duration_s;
    let strictly_better = quick_energy < full_energy_per_item - tolerance
        || quick_water < full_water_per_item - tolerance
        || quick_queue_duration_s < full.duration_s;
    no_worse && strictly_better
}

fn execute_operation(
    mode: ModeKind,
    profile: &ModeProfile,
    jobs: Vec<Job>,
    now_s: u64,
) -> (Operation, Vec<Completion>) {
    let finished_s = now_s.saturating_add(profile.duration_s);
    let energy_kwh = profile.energy_for(jobs.len());
    let fresh_water_l = profile.water_for(jobs.len());

    let completions = jobs
        .iter()
        .map(|job| Completion {
            job_id: job.id,
            mode,
            arrival_s: job.arrival_s,
            started_s: now_s,
            finished_s,
            wait_s: now_s.saturating_sub(job.arrival_s),
            deadline_missed: finished_s > job.deadline_s,
        })
        .collect();

    let operation = Operation {
        mode,
        started_s: now_s,
        finished_s,
        job_ids: jobs.iter().map(|job| job.id).collect(),
        energy_kwh,
        fresh_water_l,
    };

    (operation, completions)
}

/// Run one deterministic policy over a finite, known workload trace.
///
/// The simulator is online with respect to dispatch: future jobs are used only
/// to estimate when a full batch can be completed for urgency comparison. The
/// scheduler does not use a learned forecast. All times are seconds from the
/// workload's time origin. Jobs not eligible for the selected policy are
/// reported as unprocessed; they are never forced through an unvalidated mode.
pub fn simulate(
    jobs: &[Job],
    quick: &ModeProfile,
    full: &ModeProfile,
    policy: Policy,
) -> Result<SimulationResult, &'static str> {
    match policy {
        Policy::FullLoadOnly { .. } => {
            full.validate(None)?;
            if full.capacity < 2 {
                return Err("FullLoad capacity must be at least two");
            }
        }
        Policy::QuickCellOnly => quick.validate(Some(1))?,
        Policy::HybridResourceAware { .. }
        | Policy::HybridConservativeNoOracle { .. } => {
            quick.validate(Some(1))?;
            full.validate(None)?;
            if full.capacity < 2 {
                return Err("FullLoad capacity must be at least two");
            }
        }
    }

    let max_batch_wait_s = match policy {
        Policy::FullLoadOnly { max_batch_wait_s }
        | Policy::HybridResourceAware { max_batch_wait_s }
        | Policy::HybridConservativeNoOracle { max_batch_wait_s } => {
            if max_batch_wait_s == 0 {
                return Err("max_batch_wait_s must be positive");
            }
            max_batch_wait_s
        }
        Policy::QuickCellOnly => 0,
    };

    let mut ordered = jobs.to_vec();
    ordered.sort_by_key(|job| (job.arrival_s, job.id));
    let mut ids = HashSet::with_capacity(ordered.len());
    for job in &ordered {
        if job.deadline_s < job.arrival_s {
            return Err("job deadline must not precede arrival");
        }
        if !ids.insert(job.id) {
            return Err("job identifiers must be unique");
        }
    }

    let mut next_job = 0_usize;
    let mut pending: Vec<Job> = Vec::new();
    let mut unprocessed_job_ids = Vec::new();
    let mut completions = Vec::new();
    let mut operations = Vec::new();
    let mut quick_free_s = 0_u64;
    let mut full_free_s = 0_u64;
    let mut now_s = ordered.first().map_or(0, |job| job.arrival_s);

    while next_job < ordered.len() || !pending.is_empty() {
        while next_job < ordered.len() && ordered[next_job].arrival_s <= now_s {
            pending.push(ordered[next_job]);
            next_job += 1;
        }

        // Remove jobs that cannot be handled by any mode permitted by this policy.
        let mut retained = Vec::with_capacity(pending.len());
        for job in pending.drain(..) {
            let quick_permitted = !matches!(policy, Policy::FullLoadOnly { .. }) && quick.supports(&job);
            let full_permitted = !matches!(policy, Policy::QuickCellOnly) && full.supports(&job);
            if quick_permitted || full_permitted {
                retained.push(job);
            } else {
                unprocessed_job_ids.push(job.id);
            }
        }
        pending = retained;

        let mut dispatched = false;

        // QuickCellOnly serves the earliest-arriving eligible item as soon as it is free.
        if matches!(policy, Policy::QuickCellOnly) && quick_free_s <= now_s {
            if let Some(index) = pending.iter().position(|job| quick.supports(job)) {
                let job = pending.remove(index);
                let (operation, mut done) =
                    execute_operation(ModeKind::QuickCell, quick, vec![job], now_s);
                quick_free_s = operation.finished_s;
                operations.push(operation);
                completions.append(&mut done);
                dispatched = true;
            }
        }

        // Hybrid policies use QuickCell for jobs that cannot safely enter FullLoad,
        // or whose deadline would be missed by the conservative next-full-batch estimate.
        if matches!(
            policy,
            Policy::HybridResourceAware { .. } | Policy::HybridConservativeNoOracle { .. }
        ) && quick_free_s <= now_s
        {
            // The original HybridResourceAware policy is an offline look-ahead
            // benchmark. The conservative policy deliberately receives no future
            // arrivals, so later jobs cannot influence an earlier dispatch choice.
            let future_jobs_for_estimate: &[Job] = match policy {
                Policy::HybridResourceAware { .. } => &ordered[next_job..],
                Policy::HybridConservativeNoOracle { .. } => &[],
                _ => &[],
            };
            let predicted_finish = predicted_full_finish(
                now_s,
                &pending,
                future_jobs_for_estimate,
                full,
                full_free_s,
                max_batch_wait_s,
            );

            let full_eligible_count = pending.iter().filter(|job| full.supports(job)).count();
            let oldest_full_arrival = pending
                .iter()
                .filter(|job| full.supports(job))
                .map(|job| job.arrival_s)
                .min();
            let partial_batch_wait_expired = full_eligible_count > 0
                && full_eligible_count < full.capacity
                && oldest_full_arrival.is_some_and(|arrival| {
                    now_s >= arrival.saturating_add(max_batch_wait_s)
                });
            let all_full_jobs_are_quick_eligible = pending
                .iter()
                .filter(|job| full.supports(job))
                .all(|job| quick.supports(job));
            let quick_pareto_dominates_partial = partial_batch_wait_expired
                && all_full_jobs_are_quick_eligible
                && quick_dominates_partial_batch(quick, full, full_eligible_count);

            let selected = pending
                .iter()
                .enumerate()
                .filter(|(_, job)| quick.supports(job))
                .filter(|(_, job)| {
                    !full.supports(job)
                        || predicted_finish.is_some_and(|finish| finish > job.deadline_s)
                        || quick_pareto_dominates_partial
                })
                .min_by_key(|(_, job)| (job.deadline_s, job.arrival_s, job.id))
                .map(|(index, _)| index);

            if let Some(index) = selected {
                let job = pending.remove(index);
                let (operation, mut done) =
                    execute_operation(ModeKind::QuickCell, quick, vec![job], now_s);
                quick_free_s = operation.finished_s;
                operations.push(operation);
                completions.append(&mut done);
                dispatched = true;
            }
        }

        // FullLoad starts only when it is full or its oldest eligible item has
        // reached the explicit waiting limit.
        if !matches!(policy, Policy::QuickCellOnly) && full_free_s <= now_s {
            let eligible_count = pending.iter().filter(|job| full.supports(job)).count();
            let oldest_arrival = pending
                .iter()
                .filter(|job| full.supports(job))
                .map(|job| job.arrival_s)
                .min();

            let batch_ready = eligible_count >= full.capacity
                || oldest_arrival.is_some_and(|arrival| {
                    now_s >= arrival.saturating_add(max_batch_wait_s)
                });
            let defer_dominated_partial_to_quick = matches!(
                policy,
                Policy::HybridResourceAware { .. } | Policy::HybridConservativeNoOracle { .. }
            ) && eligible_count > 0
                && eligible_count < full.capacity
                && oldest_arrival.is_some_and(|arrival| {
                    now_s >= arrival.saturating_add(max_batch_wait_s)
                })
                && pending
                    .iter()
                    .filter(|job| full.supports(job))
                    .all(|job| quick.supports(job))
                && quick_dominates_partial_batch(quick, full, eligible_count)
                && quick_free_s > now_s;

            if batch_ready && !defer_dominated_partial_to_quick {
                let mut selected = Vec::with_capacity(full.capacity);
                let mut remaining = Vec::with_capacity(pending.len());
                for job in pending.drain(..) {
                    if full.supports(&job) && selected.len() < full.capacity {
                        selected.push(job);
                    } else {
                        remaining.push(job);
                    }
                }
                pending = remaining;

                if !selected.is_empty() {
                    let (operation, mut done) =
                        execute_operation(ModeKind::FullLoad, full, selected, now_s);
                    full_free_s = operation.finished_s;
                    operations.push(operation);
                    completions.append(&mut done);
                    dispatched = true;
                }
            }
        }

        if dispatched {
            continue;
        }

        if pending.is_empty() && next_job >= ordered.len() {
            break;
        }

        let mut next_event = ordered.get(next_job).map(|job| job.arrival_s);

        if !pending.is_empty() {
            if quick_free_s > now_s && pending.iter().any(|job| quick.supports(job))
                && !matches!(policy, Policy::FullLoadOnly { .. })
            {
                next_event = Some(next_event.map_or(quick_free_s, |t| t.min(quick_free_s)));
            }
            if full_free_s > now_s && pending.iter().any(|job| full.supports(job))
                && !matches!(policy, Policy::QuickCellOnly)
            {
                next_event = Some(next_event.map_or(full_free_s, |t| t.min(full_free_s)));
            }
            if !matches!(policy, Policy::QuickCellOnly) {
                if let Some(oldest) = pending
                    .iter()
                    .filter(|job| full.supports(job))
                    .map(|job| job.arrival_s)
                    .min()
                {
                    let timeout = oldest.saturating_add(max_batch_wait_s);
                    if timeout > now_s {
                        next_event = Some(next_event.map_or(timeout, |t| t.min(timeout)));
                    }
                }
            }
        }

        let Some(next_time) = next_event else {
            unprocessed_job_ids.extend(pending.drain(..).map(|job| job.id));
            break;
        };
        if next_time <= now_s {
            return Err("scheduler failed to advance to a future event");
        }
        now_s = next_time;
    }

    completions.sort_by_key(|completion| (completion.finished_s, completion.arrival_s, completion.job_id));
    operations.sort_by_key(|operation| (operation.started_s, operation.mode as u8));
    unprocessed_job_ids.sort_unstable();

    let total_energy_kwh: f64 = operations.iter().map(|op| op.energy_kwh).sum();
    let total_fresh_water_l: f64 = operations.iter().map(|op| op.fresh_water_l).sum();
    if !total_energy_kwh.is_finite() || !total_fresh_water_l.is_finite() {
        return Err("total resource estimate is non-finite");
    }

    let mut waits: Vec<u64> = completions.iter().map(|completion| completion.wait_s).collect();
    waits.sort_unstable();
    let mean_wait_s = if waits.is_empty() {
        0.0
    } else {
        waits.iter().map(|value| *value as f64).sum::<f64>() / waits.len() as f64
    };
    let p95_wait_s = if waits.is_empty() {
        0
    } else {
        let index = ((waits.len() as f64 * 0.95).ceil() as usize)
            .saturating_sub(1)
            .min(waits.len() - 1);
        waits[index]
    };

    let mut latencies: Vec<u64> = completions
        .iter()
        .map(|completion| completion.finished_s.saturating_sub(completion.arrival_s))
        .collect();
    latencies.sort_unstable();
    let mean_latency_s = if latencies.is_empty() {
        0.0
    } else {
        latencies.iter().map(|value| *value as f64).sum::<f64>() / latencies.len() as f64
    };
    let p95_latency_s = if latencies.is_empty() {
        0
    } else {
        let index = ((latencies.len() as f64 * 0.95).ceil() as usize)
            .saturating_sub(1)
            .min(latencies.len() - 1);
        latencies[index]
    };

    let deadline_misses = completions.iter().filter(|completion| completion.deadline_missed).count();
    let workload_start_s = ordered.first().map_or(0, |job| job.arrival_s);
    let makespan_s = completions
        .iter()
        .map(|completion| completion.finished_s)
        .max()
        .unwrap_or(workload_start_s)
        .saturating_sub(workload_start_s);
    let quick_cell_cycles = operations.iter().filter(|op| op.mode == ModeKind::QuickCell).count();
    let full_load_cycles = operations.iter().filter(|op| op.mode == ModeKind::FullLoad).count();

    Ok(SimulationResult {
        completions,
        operations,
        unprocessed_job_ids,
        total_energy_kwh,
        total_fresh_water_l,
        quick_cell_cycles,
        full_load_cycles,
        deadline_misses,
        mean_wait_s,
        p95_wait_s,
        mean_latency_s,
        p95_latency_s,
        makespan_s,
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DemandPattern {
    SparseHousehold,
    MealBursts,
    Irregular,
}

fn next_random(state: &mut u64) -> u64 {
    *state = state
        .wrapping_mul(6_364_136_223_846_793_005)
        .wrapping_add(1_442_695_040_888_963_407);
    *state
}

/// Generate reproducible *synthetic* arrivals. These are scenario fixtures,
/// not measured household-use data. The seed and pattern are explicit.
pub fn generate_workload(seed: u64, item_count: usize, pattern: DemandPattern) -> Vec<Job> {
    let mut state = seed;
    let mut now_s = 0_u64;
    let mut jobs = Vec::with_capacity(item_count);

    for id in 0..item_count {
        let interarrival = next_random(&mut state);
        let gap = match pattern {
            DemandPattern::SparseHousehold => 1_800 + interarrival % 7_200,
            DemandPattern::MealBursts => {
                if id % 14 == 0 { 10_800 + interarrival % 3_600 } else { 20 + interarrival % 180 }
            }
            DemandPattern::Irregular => 120 + interarrival % 5_400,
        };
        if id > 0 {
            now_s = now_s.saturating_add(gap);
        }

        let attributes = next_random(&mut state);
        let soil = match attributes % 5 {
            0 => SoilClass::Protein,
            1 => SoilClass::Starch,
            2 => SoilClass::Fat,
            3 => SoilClass::Beverage,
            _ => SoilClass::Mixed,
        };
        let urgent = (attributes >> 8) % 5 == 0;
        let requires_sanitization = (attributes >> 16) % 17 == 0;
        let deadline_s = now_s.saturating_add(if urgent { 1_800 } else { 21_600 });

        jobs.push(Job {
            id: id as u64,
            arrival_s: now_s,
            deadline_s,
            soil,
            requires_sanitization,
        });
    }

    jobs
}

/// Explicit illustrative inputs for smoke tests and example runs.
///
/// At full capacity, the FullLoad profile totals approximately 0.39 kWh and
/// 6.7 L for 14 items. These are hypothetical design targets, not measured
/// values or manufacturer claims. The QuickCell profile totals 0.05 kWh and
/// 0.7 L per item, also a hypothetical target.
pub fn illustrative_profiles() -> (ModeProfile, ModeProfile) {
    let quick = ModeProfile {
        name: "QuickCell-illustrative".to_owned(),
        capacity: 1,
        duration_s: 300,
        base_energy_kwh: 0.015,
        energy_per_item_kwh: 0.035,
        base_fresh_water_l: 0.2,
        fresh_water_per_item_l: 0.5,
        supported_soils_mask: ALL_SOILS_MASK,
        supports_sanitization: true,
        cleaning_and_rinse_validated: true,
    };

    let full = ModeProfile {
        name: "FullLoad-illustrative".to_owned(),
        capacity: 14,
        duration_s: 7_200,
        base_energy_kwh: 0.12,
        energy_per_item_kwh: 0.019_285_714_285_714_285,
        base_fresh_water_l: 2.0,
        fresh_water_per_item_l: 0.335_714_285_714_285_7,
        supported_soils_mask: ALL_SOILS_MASK,
        supports_sanitization: true,
        cleaning_and_rinse_validated: true,
    };

    (quick, full)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_job(id: u64, arrival_s: u64, deadline_s: u64) -> Job {
        Job {
            id,
            arrival_s,
            deadline_s,
            soil: SoilClass::Starch,
            requires_sanitization: false,
        }
    }

    fn profiles() -> (ModeProfile, ModeProfile) {
        illustrative_profiles()
    }

    #[test]
    fn full_load_is_more_resource_efficient_at_full_capacity_in_illustrative_case() {
        let (quick, full) = profiles();
        let jobs: Vec<Job> = (0..14)
            .map(|id| sample_job(id, id, 86_400))
            .collect();

        let batch = simulate(
            &jobs,
            &quick,
            &full,
            Policy::FullLoadOnly { max_batch_wait_s: 10_800 },
        )
        .unwrap();
        let individual = simulate(&jobs, &quick, &full, Policy::QuickCellOnly).unwrap();

        assert_eq!(batch.completed_items(), 14);
        assert_eq!(batch.full_load_cycles, 1);
        assert!(batch.total_energy_kwh < individual.total_energy_kwh);
        assert!(batch.total_fresh_water_l < individual.total_fresh_water_l);
    }

    #[test]
    fn quick_cell_reduces_single_item_latency_and_resource_use_in_illustrative_case() {
        let (quick, full) = profiles();
        let jobs = [sample_job(1, 0, 86_400)];

        let batch = simulate(
            &jobs,
            &quick,
            &full,
            Policy::FullLoadOnly { max_batch_wait_s: 10_800 },
        )
        .unwrap();
        let individual = simulate(&jobs, &quick, &full, Policy::QuickCellOnly).unwrap();

        assert!(individual.makespan_s < batch.makespan_s);
        assert!(individual.total_energy_kwh < batch.total_energy_kwh);
        assert!(individual.total_fresh_water_l < batch.total_fresh_water_l);
    }

    #[test]
    fn quickcell_does_not_dominate_if_serial_queue_service_is_slower() {
        let (mut quick, full) = profiles();
        quick.duration_s = 900;
        assert!(!quick_dominates_partial_batch(&quick, &full, 10));
    }

    #[test]
    fn hybrid_uses_quickcell_when_a_timed_out_partial_batch_is_pareto_dominated() {
        let (quick, full) = profiles();
        let jobs = [
            sample_job(1, 0, 86_400),
            sample_job(2, 60, 86_400),
        ];

        let full_only = simulate(
            &jobs,
            &quick,
            &full,
            Policy::FullLoadOnly { max_batch_wait_s: 300 },
        )
        .unwrap();
        let hybrid = simulate(
            &jobs,
            &quick,
            &full,
            Policy::HybridResourceAware { max_batch_wait_s: 300 },
        )
        .unwrap();

        assert_eq!(hybrid.quick_cell_cycles, 2);
        assert_eq!(hybrid.full_load_cycles, 0);
        assert!(hybrid.total_energy_kwh < full_only.total_energy_kwh);
        assert!(hybrid.total_fresh_water_l < full_only.total_fresh_water_l);
    }

    #[test]
    fn hybrid_keeps_full_load_when_a_dense_batch_dominates_quickcell() {
        let (quick, full) = profiles();
        let jobs: Vec<Job> = (0..14)
            .map(|id| sample_job(id, id, 86_400))
            .collect();

        let hybrid = simulate(
            &jobs,
            &quick,
            &full,
            Policy::HybridResourceAware { max_batch_wait_s: 300 },
        )
        .unwrap();

        assert_eq!(hybrid.quick_cell_cycles, 0);
        assert_eq!(hybrid.full_load_cycles, 1);
        assert_eq!(hybrid.completed_items(), 14);
    }

    #[test]
    fn hybrid_routes_urgent_job_to_quickcell_and_batches_remainder() {
        let (quick, full) = profiles();
        let mut jobs: Vec<Job> = (0..15)
            .map(|id| sample_job(id, id, 86_400))
            .collect();
        jobs[0].deadline_s = 600;

        let result = simulate(
            &jobs,
            &quick,
            &full,
            Policy::HybridResourceAware { max_batch_wait_s: 10_800 },
        )
        .unwrap();

        assert_eq!(result.quick_cell_cycles, 1);
        assert_eq!(result.full_load_cycles, 1);
        assert_eq!(result.completed_items(), 15);
        assert_eq!(result.deadline_misses, 0);
        assert!(result.completions.iter().any(|completion| {
            completion.job_id == 0 && completion.mode == ModeKind::QuickCell
        }));
    }

    #[test]
    fn conservative_hybrid_is_independent_of_future_arrival_oracle() {
        let (quick, full) = profiles();
        let first = sample_job(1, 0, 9_000);
        // Thirteen later arrivals make a 14-item FullLoad batch available at t=1.
        let later_jobs: Vec<Job> = (2..15).map(|id| sample_job(id, 1, 20_000)).collect();
        let policy = Policy::HybridConservativeNoOracle {
            max_batch_wait_s: 3_600,
        };

        let one_job = simulate(&[first], &quick, &full, policy).unwrap();
        let mut trace_with_later_arrivals = vec![first];
        trace_with_later_arrivals.extend(later_jobs.iter().copied());
        let with_later_arrival =
            simulate(&trace_with_later_arrivals, &quick, &full, policy).unwrap();
        let offline_lookahead = simulate(
            &trace_with_later_arrivals,
            &quick,
            &full,
            Policy::HybridResourceAware {
                max_batch_wait_s: 3_600,
            },
        )
        .unwrap();

        let first_mode = |result: &SimulationResult| {
            result
                .completions
                .iter()
                .find(|completion| completion.job_id == 1)
                .map(|completion| completion.mode)
                .unwrap()
        };

        // With no observed second item, the conservative estimate assumes the
        // full batch may wait until timeout and therefore protects the deadline.
        // Appending a future arrival must not retroactively change that decision.
        assert_eq!(first_mode(&one_job), ModeKind::QuickCell);
        assert_eq!(first_mode(&with_later_arrival), ModeKind::QuickCell);

        // The offline policy is intentionally an optimistic reference: it sees
        // the item arriving at t=1 and batches both items into FullLoad.
        assert_eq!(first_mode(&offline_lookahead), ModeKind::FullLoad);
    }

    #[test]
    fn cleaning_and_rinse_gate_is_fail_closed() {
        let (mut quick, mut full) = profiles();
        quick.cleaning_and_rinse_validated = false;
        full.cleaning_and_rinse_validated = false;

        let result = simulate(
            &[sample_job(1, 0, 600)],
            &quick,
            &full,
            Policy::HybridResourceAware { max_batch_wait_s: 300 },
        )
        .unwrap();

        assert_eq!(result.completed_items(), 0);
        assert_eq!(result.unprocessed_job_ids, vec![1]);
        assert_eq!(result.total_energy_kwh, 0.0);
        assert_eq!(result.total_fresh_water_l, 0.0);
    }

    #[test]
    fn soil_and_sanitization_eligibility_are_hard_constraints() {
        let (mut quick, mut full) = profiles();
        quick.supported_soils_mask = SoilClass::Starch.mask();
        full.supported_soils_mask = SoilClass::Starch.mask();
        quick.supports_sanitization = false;
        full.supports_sanitization = false;

        let mut protein = sample_job(1, 0, 600);
        protein.soil = SoilClass::Protein;
        let mut sanitization = sample_job(2, 0, 600);
        sanitization.requires_sanitization = true;

        let result = simulate(
            &[protein, sanitization],
            &quick,
            &full,
            Policy::HybridResourceAware { max_batch_wait_s: 300 },
        )
        .unwrap();
        assert_eq!(result.completed_items(), 0);
        assert_eq!(result.unprocessed_job_ids, vec![1, 2]);
    }

    #[test]
    fn seeded_workload_is_reproducible_and_has_valid_deadlines() {
        let first = generate_workload(42, 500, DemandPattern::Irregular);
        let second = generate_workload(42, 500, DemandPattern::Irregular);
        assert_eq!(first, second);
        assert!(first.iter().all(|job| job.deadline_s >= job.arrival_s));
    }

    #[test]
    fn quickcell_only_does_not_require_an_unused_full_load_profile() {
        let (quick, mut full) = profiles();
        full.capacity = 0;
        full.energy_per_item_kwh = f64::NAN;
        let result = simulate(
            &[sample_job(1, 0, 600)],
            &quick,
            &full,
            Policy::QuickCellOnly,
        )
        .unwrap();
        assert_eq!(result.completed_items(), 1);
        assert_eq!(result.full_load_cycles, 0);
    }

    #[test]
    fn invalid_resource_coefficients_are_rejected() {
        let (quick, mut full) = profiles();
        full.energy_per_item_kwh = f64::NAN;
        assert!(simulate(
            &[sample_job(1, 0, 1_000)],
            &quick,
            &full,
            Policy::FullLoadOnly { max_batch_wait_s: 100 },
        )
        .is_err());
    }

    #[test]
    fn duplicate_job_ids_are_rejected() {
        let (quick, full) = profiles();
        let jobs = [sample_job(1, 0, 1_000), sample_job(1, 10, 1_000)];
        assert!(simulate(
            &jobs,
            &quick,
            &full,
            Policy::QuickCellOnly
        )
        .is_err());
    }
}


#[cfg(test)]
mod evidence_bound_mode_tests {
    use super::*;
    use symthaea_dishwasher_design::quality::{
        qualify_pilot_evidence, Endpoint, EndpointCriterion, EvidenceKind, LimitDirection,
        OutcomeObservation, PilotPolicy, QualificationScope,
    };

    fn envelope(
        programme: &str,
        soil: SoilClass,
        occupancy: usize,
        machine_model: &str,
        detergent_batch: &str,
    ) -> PilotEvidenceEnvelope {
        let item_ids: Vec<String> = (0..occupancy)
            .map(|index| format!("item-{index:02}"))
            .collect();
        let scope = QualificationScope {
            machine_model: machine_model.to_owned(),
            programme: programme.to_owned(),
            soil_class: soil.as_label().to_owned(),
            surface_material: "ceramic".to_owned(),
            item_set_id: format!("{}-{occupancy}-item-set", soil.as_label()),
            item_ids: item_ids.clone(),
            detergent_batch_id: detergent_batch.to_owned(),
            water_batch_id: "water-lot-1".to_owned(),
            water_hardness_ppm_as_caco3: 75,
            inlet_temperature_millic: 15_000,
            ambient_temperature_millic: 20_000,
            ambient_relative_humidity_permille: 500,
            protocol_id: "pilot-protocol-v1".to_owned(),
            raw_archive_sha256: "a".repeat(64),
        };
        let criteria = vec![
            EndpointCriterion {
                endpoint: Endpoint::SoilRemovalResidual,
                criterion_id: "soil-limit-v1".to_owned(),
                metric_id: "residual_soil_area_fraction".to_owned(),
                unit: "fraction".to_owned(),
                direction: LimitDirection::AtMost,
                limit: 0.05,
                criterion_evidence_sha256: "b".repeat(64),
            },
            EndpointCriterion {
                endpoint: Endpoint::FinalRinseResidue,
                criterion_id: "rinse-limit-v1".to_owned(),
                metric_id: "final_rinse_residue".to_owned(),
                unit: "mg/L".to_owned(),
                direction: LimitDirection::AtMost,
                limit: 5.0,
                criterion_evidence_sha256: "c".repeat(64),
            },
            EndpointCriterion {
                endpoint: Endpoint::CrossContamination,
                criterion_id: "cross-transfer-limit-v1".to_owned(),
                metric_id: "marker_transfer_mass".to_owned(),
                unit: "mg".to_owned(),
                direction: LimitDirection::AtMost,
                limit: 0.01,
                criterion_evidence_sha256: "d".repeat(64),
            },
        ];
        let endpoints = [
            Endpoint::SoilRemovalResidual,
            Endpoint::FinalRinseResidue,
            Endpoint::CrossContamination,
        ];
        let mut observations = Vec::new();
        for run in 1..=5 {
            for item_id in &item_ids {
                for endpoint in endpoints {
                    let criterion = criteria
                        .iter()
                        .find(|criterion| criterion.endpoint == endpoint)
                        .unwrap();
                    let (method, measured_value, uncertainty) = match endpoint {
                        Endpoint::SoilRemovalResidual => ("fluorescence-assay-v1", 0.02, 0.005),
                        Endpoint::FinalRinseResidue => ("rinse-assay-v1", 2.0, 0.5),
                        Endpoint::CrossContamination => ("witness-coupon-v1", 0.003, 0.001),
                        _ => unreachable!(),
                    };
                    observations.push(OutcomeObservation {
                        run_id: format!("run-{run:02}"),
                        item_id: item_id.clone(),
                        endpoint,
                        criterion_id: criterion.criterion_id.clone(),
                        metric_id: criterion.metric_id.clone(),
                        evidence_kind: EvidenceKind::IndependentOutcomeAssay,
                        method_id: method.to_owned(),
                        protocol_id: "pilot-protocol-v1".to_owned(),
                        measured_value,
                        expanded_uncertainty: uncertainty,
                        unit: criterion.unit.clone(),
                        evidence_ref: format!("evidence-{run}-{item_id}-{endpoint:?}"),
                        calibration_bundle_sha256: "1".repeat(64),
                    });
                }
            }
        }
        qualify_pilot_evidence(
            scope,
            PilotPolicy {
                minimum_independent_runs: 5,
                require_drying_endpoint: false,
                require_relative_microbiology_endpoint: false,
            },
            criteria,
            observations,
        )
        .unwrap()
    }

    fn mode_profile(programme: &str, capacity: usize, supports_sanitization: bool) -> ModeProfile {
        ModeProfile {
            name: programme.to_owned(),
            capacity,
            duration_s: 900,
            base_energy_kwh: 0.02,
            energy_per_item_kwh: 0.01,
            base_fresh_water_l: 0.2,
            fresh_water_per_item_l: 0.3,
            supported_soils_mask: ALL_SOILS_MASK,
            supports_sanitization,
            cleaning_and_rinse_validated: false,
        }
    }

    #[test]
    fn derives_supported_soils_from_a_complete_pilot_occupancy_ladder() {
        let mode = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("quickcell-v1", 1, false),
            vec![envelope("quickcell-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1")],
        )
        .unwrap();

        assert!(mode.profile().supports(&Job {
            id: 1,
            arrival_s: 0,
            deadline_s: 2_000,
            soil: SoilClass::Starch,
            requires_sanitization: false,
        }));
        assert!(!mode.profile().supports(&Job {
            id: 2,
            arrival_s: 0,
            deadline_s: 2_000,
            soil: SoilClass::Protein,
            requires_sanitization: false,
        }));
    }

    #[test]
    fn refuses_to_advertise_capacity_without_each_intermediate_occupancy() {
        let result = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("full-load-v1", 2, false),
            vec![envelope("full-load-v1", SoilClass::Starch, 2, "prototype-a", "detergent-1")],
        );
        assert!(matches!(
            result,
            Err(EvidenceBoundModeError::MissingSoilOccupancy {
                soil: SoilClass::Starch,
                occupancy: 1
            })
        ));
    }

    #[test]
    fn rejects_evidence_from_different_machine_or_detergent_batches() {
        let result = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("full-load-v1", 2, false),
            vec![
                envelope("full-load-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1"),
                envelope("full-load-v1", SoilClass::Starch, 2, "prototype-b", "detergent-1"),
            ],
        );
        assert_eq!(result, Err(EvidenceBoundModeError::InconsistentPhysicalScope));

        let result = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("full-load-v1", 2, false),
            vec![
                envelope("full-load-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1"),
                envelope("full-load-v1", SoilClass::Starch, 2, "prototype-a", "detergent-2"),
            ],
        );
        assert_eq!(result, Err(EvidenceBoundModeError::InconsistentPhysicalScope));
    }

    #[test]
    fn rejects_programme_mismatch_and_duplicate_soil_occupancy() {
        let mismatch = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("quickcell-v2", 1, false),
            vec![envelope("quickcell-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1")],
        );
        assert_eq!(mismatch, Err(EvidenceBoundModeError::ProgrammeMismatch));

        let duplicate = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("quickcell-v1", 1, false),
            vec![
                envelope("quickcell-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1"),
                envelope("quickcell-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1"),
            ],
        );
        assert!(matches!(
            duplicate,
            Err(EvidenceBoundModeError::DuplicateSoilOccupancy {
                soil: SoilClass::Starch,
                occupancy: 1
            })
        ));
    }

    #[test]
    fn sanitization_cannot_be_enabled_by_cleaning_and_rinse_pilot_data() {
        let result = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("quickcell-v1", 1, true),
            vec![envelope("quickcell-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1")],
        );
        assert_eq!(
            result,
            Err(EvidenceBoundModeError::SanitizationRequiresSeparateCertification)
        );
    }

    #[test]
    fn evidence_bound_profiles_can_enter_the_scheduler_without_a_free_boolean() {
        let quick = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("quickcell-v1", 1, false),
            vec![envelope("quickcell-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1")],
        )
        .unwrap();
        let full = EvidenceBoundMode::from_pilot_evidence(
            mode_profile("full-load-v1", 2, false),
            vec![
                envelope("full-load-v1", SoilClass::Starch, 1, "prototype-a", "detergent-1"),
                envelope("full-load-v1", SoilClass::Starch, 2, "prototype-a", "detergent-1"),
            ],
        )
        .unwrap();

        let result = simulate_with_pilot_evidence(
            &[Job {
                id: 7,
                arrival_s: 0,
                deadline_s: 2_000,
                soil: SoilClass::Starch,
                requires_sanitization: false,
            }],
            &quick,
            &full,
            Policy::QuickCellOnly,
        )
        .unwrap();
        assert_eq!(result.completed_items(), 1);
    }
}
